const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const canberra = ee.Geometry.Point([149.1300, -35.2809]).buffer(10000); // 10km buffer around Canberra
  const startDate = '2020-01-14';
  const endDate = '2020-01-22';

  // 2. Data Acquisition - GPM IMERG Final Precipitation
  const precipCol = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .filterBounds(canberra);

  const colSize = precipCol.size().getInfo();
  console.log(`Images found: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over the period
  const totalPrecip = precipCol.sum().select('precipitationCal');

  // Check valid pixels
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: canberra,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitationCal').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation in mm
  const meanPrecip = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: canberra,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitationCal').getInfo();

  // Convert mm to inches
  const precipInches = meanPrecip / 25.4;

  console.log(`Total rainfall (mm): ${meanPrecip.toFixed(2)}`);
  console.log(`Total rainfall (inches): ${precipInches.toFixed(2)}`);

  // 5. Validation & Final Answer
  if (meanPrecip === null || !isFinite(meanPrecip) || precipInches === null || !isFinite(precipInches)) {
    console.log("<answer>C3</answer>");
  } else if (precipInches > 8) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
